lib/notes.source:
import { attio } from adapters
import { crm_cred } from credentials
crm = connect attio using crm_cred
prefix = "lib"
type Mood = <"calm" | "loud">
export node Note {
  body: <text>
}
export function note(n: <Note>, tag: <text>) {
  copy = first(map([n], (v) => {
    g = graph { ...v }
    return g
  }))
  write crm-[:notes]-> { body: "${prefix}:${tag}:${copy.body}" }
  return Text.upper(copy.body)
}

